preConditionHook:
// The breakout test / breakout pullback. Price closed above a prior swing
// high within the last maxWaitBars bars, and this bar comes back DOWN to
// that broken level and holds above it: the low reaches it (within tol) but
// does not blow more than maxOvershootAtr ATRs through it. Short is the
// mirror on a swing low, with the pullback coming back UP to the level.
//
// THE LEVEL IS A CONFIRMED SWING PIVOT, not a highest-window: the EL twin
// calls SwingHigh(1, high, strength, lookback) for the price and
// SwingHighBar for the same pivot's bars-ago count. The merged pseudocode
// fixed the level at highest(high, lookback) one bar before the breakout
// bar, which at its default lookback = 1 is just the bar before it; the
// pivot form is the same idea with the noise filtered by `strength`, and it
// is what the rest of the corpus will build on. The pivot scan is INLINED
// here rather than reaching into SwingHigh.json -- rules in this corpus
// never reference each other.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min):
//   * the pivot test is MIXED -- AT OR ABOVE the `strength` OLDER bars,
//     STRICTLY ABOVE the `strength` NEWER bars -- so a flat top yields
//     exactly one pivot, the later of the equal bars;
//   * the confirmation lag is exactly `strength` bars, never 0 or 1;
//   * `lookback` is EL's Length: candidate offsets 0..lookback-1 counted
//     from the current bar inclusive, and the neighbourhood test reaches
//     `strength` bars past the window, so the deepest index the scan touches
//     is lookback - 1 + strength;
//   * a window with no pivot returns the -1 SENTINEL, guarded by haveHigh /
//     haveLow below: -1 as a price sits under every real price and would
//     otherwise sail through the hold-above test;
//   * the comparisons carry the 2.22e-12 relational tolerance, hence el_gt /
//     el_ge inside the scan rather than raw > and >=.
// The low side's tie sense is the mirror of the measured high-side rule
// rather than an observation. There is no WFSafe_SwingHigh in the MultiWalk
// library, so plain EL governs.
//
// THE PIVOT MUST PRECEDE THE BREAKOUT, hence `kk < pivotHighBar` in the
// breakout scan: a close above the level from before the pivot printed is
// not a breakout OF that pivot. Since the confirmation lag puts pivotHighBar
// at `strength` or more, at maxWaitBars <= strength the guard never bites.
//
// Tolerance in ATR, not ticks: the sources give 1-2 ticks and 0.1-0.2 ATR
// for the same test, MinMove/PriceScale are unregistered and the engine
// exposes no tick size, so both bands are ATR fractions -- the same
// substitution PriorSessionLevelTest and PullbackFromRecentHigh make.
const int pivStrength = (int)strength;
const int pivWindow = (int)lookback;
pivotHighBar = -1;
levelHigh = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotHighBar = j; levelHigh = high[j]; break; }
}
pivotLowBar = -1;
levelLow = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotLowBar = j; levelLow = low[j]; break; }
}
haveHigh = (pivotHighBar != -1);
haveLow = (pivotLowBar != -1);
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right, and
// folding it to S += in - out rounds differently (@OJ 2015-02-20). One call
// site, here in the hook, so exactly one accumulator advances per bar.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
tol = toleranceAtr * atr;
overshoot = maxOvershootAtr * atr;
brokeOutUp = false;
brokeOutDn = false;
for (int kk = 1; kk <= (int)maxWaitBars; ++kk) {
    if (kk < pivotHighBar && el_gt(close[kk], levelHigh)) brokeOutUp = true;
    if (kk < pivotLowBar && el_lt(close[kk], levelLow)) brokeOutDn = true;
}
